// Pre-existing functions expecting specific pointer types
#include <memory>
void f1(std::shared_ptr<int> p);
void f2(int* p);

// A generic function that forwards its argument
template<typename FuncType, typename PtrType>
void forward_call(FuncType func, PtrType ptr) {
  func(ptr);
}

// --- Calls that fail compilation ---
// forward_call(f1, 0);    // FAILS: PtrType is deduced as `int`
// forward_call(f2, NULL); // FAILS: PtrType is deduced as `long` (typically)

// --- Calls that succeed ---
forward_call(f1, nullptr); // OK: PtrType is `std::nullptr_t`
forward_call(f2, nullptr); // OK: PtrType is `std::nullptr_t`
